use split_decls_genesis :: ourprelude :: * ; use std :: borrow :: Cow ; use std :: mem ; use rustc_ast :: token :: Token ; use rustc_ast :: tokenstream :: { AttrsTarget , LazyAttrTokenStream , NodeRange , ParserRange , Spacing , TokenCursor , } ; use rustc_ast :: { self as ast , AttrVec , Attribute , HasAttrs , HasTokens } ; use rustc_data_structures :: fx :: FxHashSet ; use rustc_errors :: PResult ; use rustc_session :: parse :: ParseSess ; use rustc_span :: { DUMMY_SP , sym } ; use thin_vec :: ThinVec ; use super :: { Capturing , ForceCollect , Parser , Trailing } ; #[derive (Clone , Debug)] pub (super) struct CollectPos { start_token : (Token , Spacing) , cursor_snapshot : TokenCursor , start_pos : u32 , } pub (super) enum UsePreAttrPos { No , Yes , } #[doc = " A wrapper type to ensure that the parser handles outer attributes correctly."] #[doc = " When we parse outer attributes, we need to ensure that we capture tokens"] #[doc = " for the attribute target. This allows us to perform cfg-expansion on"] #[doc = " a token stream before we invoke a derive proc-macro."] #[doc = ""] #[doc = " This wrapper prevents direct access to the underlying `ast::AttrVec`."] #[doc = " Parsing code can only get access to the underlying attributes"] #[doc = " by passing an `AttrWrapper` to `collect_tokens`."] #[doc = " This makes it difficult to accidentally construct an AST node"] #[doc = " (which stores an `ast::AttrVec`) without first collecting tokens."] #[doc = ""] #[doc = " This struct has its own module, to ensure that the parser code"] #[doc = " cannot directly access the `attrs` field."] #[derive (Debug , Clone)] pub (super) struct AttrWrapper { attrs : AttrVec , start_pos : Option < u32 > , } impl AttrWrapper { pub (super) fn new (attrs : AttrVec , start_pos : u32) -> AttrWrapper { AttrWrapper { attrs , start_pos : Some (start_pos) } } pub (super) fn empty () -> AttrWrapper { AttrWrapper { attrs : AttrVec :: new () , start_pos : None } } pub (super) fn take_for_recovery (self , psess : & ParseSess) -> AttrVec { psess . dcx () . span_delayed_bug (self . attrs . get (0) . map (| attr | attr . span) . unwrap_or (DUMMY_SP) , "AttrVec is taken for recovery but no error is produced" ,) ; self . attrs } #[doc = " Prepend `self.attrs` to `attrs`."] pub (super) fn prepend_to_nt_inner (mut self , attrs : & mut AttrVec) { mem :: swap (attrs , & mut self . attrs) ; attrs . extend (self . attrs) ; } pub (super) fn is_empty (& self) -> bool { self . attrs . is_empty () } } #[doc = " Returns `true` if `attrs` contains a `cfg` or `cfg_attr` attribute"] fn has_cfg_or_cfg_attr (attrs : & [Attribute]) -> bool { attrs . iter () . any (| attr | { attr . ident () . is_some_and (| ident | ident . name == sym :: cfg || ident . name == sym :: cfg_attr) }) } impl < 'a > Parser < 'a > { pub (super) fn collect_pos (& self) -> CollectPos { CollectPos { start_token : (self . token , self . token_spacing) , cursor_snapshot : self . token_cursor . clone () , start_pos : self . num_bump_calls , } } #[doc = " Parses code with `f`. If appropriate, it records the tokens (in"] #[doc = " `LazyAttrTokenStream` form) that were parsed in the result, accessible"] #[doc = " via the `HasTokens` trait. The `Trailing` part of the callback's"] #[doc = " result indicates if an extra token should be captured, e.g. a comma or"] #[doc = " semicolon. The `UsePreAttrPos` part of the callback's result indicates"] #[doc = " if we should use `pre_attr_pos` as the collection start position (only"] #[doc = " required in a few cases)."] #[doc = ""] #[doc = " The `attrs` passed in are in `AttrWrapper` form, which is opaque. The"] #[doc = " `AttrVec` within is passed to `f`. See the comment on `AttrWrapper` for"] #[doc = " details."] #[doc = ""] #[doc = " `pre_attr_pos` is the position before the outer attributes (or the node"] #[doc = " itself, if no outer attributes are present). It is only needed if `f`"] #[doc = " can return `UsePreAttrPos::Yes`."] #[doc = ""] #[doc = " Note: If your callback consumes an opening delimiter (including the"] #[doc = " case where `self.token` is an opening delimiter on entry to this"] #[doc = " function), you must also consume the corresponding closing delimiter."] #[doc = " E.g. you can consume `something ([{ }])` or `([{}])`, but not `([{}]`."] #[doc = " This restriction isn't a problem in practice, because parsed AST items"] #[doc = " always have matching delimiters."] #[doc = ""] #[doc = " The following example code will be used to explain things in comments"] #[doc = " below. It has an outer attribute and an inner attribute. Parsing it"] #[doc = " involves two calls to this method, one of which is indirectly"] #[doc = " recursive."] #[doc = " ```ignore (fake attributes)"] #[doc = " #[cfg_eval]                         // token pos"] #[doc = " mod m {                             //   0.. 3"] #[doc = "     #[cfg_attr(cond1, attr1)]       //   3..12"] #[doc = "     fn g() {                        //  12..17"] #[doc = "         #![cfg_attr(cond2, attr2)]  //  17..27"] #[doc = "         let _x = 3;                 //  27..32"] #[doc = "     }                               //  32..33"] #[doc = " }                                   //  33..34"] #[doc = " ```"] pub (super) fn collect_tokens < R : HasAttrs + HasTokens > (& mut self , pre_attr_pos : Option < CollectPos > , attrs : AttrWrapper , force_collect : ForceCollect , f : impl FnOnce (& mut Self , AttrVec) -> PResult < 'a , (R , Trailing , UsePreAttrPos) > ,) -> PResult < 'a , R > { let possible_capture_mode = self . capture_cfg ; let needs_collection = matches ! (force_collect , ForceCollect :: Yes) || needs_tokens (& attrs . attrs) || R :: SUPPORTS_CUSTOM_INNER_ATTRS || possible_capture_mode ; if ! needs_collection { return Ok (f (self , attrs . attrs) ? . 0) ; } let mut collect_pos = self . collect_pos () ; let has_outer_attrs = ! attrs . attrs . is_empty () ; let parser_replacements_start = self . capture_state . parser_replacements . len () ; let (mut ret , capture_trailing , use_pre_attr_pos) = { let prev_capturing = mem :: replace (& mut self . capture_state . capturing , Capturing :: Yes) ; let res = f (self , attrs . attrs) ; self . capture_state . capturing = prev_capturing ; res ? } ; let ret_can_hold_tokens = matches ! (ret . tokens_mut () , Some (None)) ; let mut seen_indices = FxHashSet :: default () ; for (i , attr) in ret . attrs () . iter () . enumerate () { let is_unseen = self . capture_state . seen_attrs . insert (attr . id) ; if ! is_unseen { seen_indices . insert (i) ; } } let ret_attrs : Cow < '_ , [Attribute] > = if seen_indices . is_empty () { Cow :: Borrowed (ret . attrs ()) } else { let ret_attrs = ret . attrs () . iter () . enumerate () . filter_map (| (i , attr) | { if seen_indices . contains (& i) { None } else { Some (attr . clone ()) } }) . collect () ; Cow :: Owned (ret_attrs) } ; let definite_capture_mode = self . capture_cfg && matches ! (self . capture_state . capturing , Capturing :: Yes) && has_cfg_or_cfg_attr (& ret_attrs) ; if ! definite_capture_mode && ! ret_can_hold_tokens { return Ok (ret) ; } let needs_collection = matches ! (force_collect , ForceCollect :: Yes) || needs_tokens (& ret_attrs) || definite_capture_mode ; if ! needs_collection { return Ok (ret) ; } if matches ! (use_pre_attr_pos , UsePreAttrPos :: Yes) { collect_pos = pre_attr_pos . unwrap () ; } let parser_replacements_end = self . capture_state . parser_replacements . len () ; assert ! (! (self . break_last_token > 0 && matches ! (capture_trailing , Trailing :: Yes)) , "Cannot have break_last_token > 0 and have trailing token") ; assert ! (self . break_last_token <= 2 , "cannot break token more than twice") ; let end_pos = self . num_bump_calls + capture_trailing as u32 + if self . break_last_token == 0 { 0 } else { 1 } ; let num_calls = end_pos - collect_pos . start_pos ; let mut inner_attr_parser_replacements = Vec :: new () ; for attr in ret_attrs . iter () { if attr . style == ast :: AttrStyle :: Inner { if let Some (inner_attr_parser_range) = self . capture_state . inner_attr_parser_ranges . remove (& attr . id) { inner_attr_parser_replacements . push ((inner_attr_parser_range , None)) ; } else { self . dcx () . span_delayed_bug (attr . span , "Missing token range for attribute") ; } } } let node_replacements = if parser_replacements_start == parser_replacements_end && inner_attr_parser_replacements . is_empty () { ThinVec :: new () } else { self . capture_state . parser_replacements [parser_replacements_start .. parser_replacements_end] . iter () . cloned () . chain (inner_attr_parser_replacements) . map (| (parser_range , data) | { (NodeRange :: new (parser_range , collect_pos . start_pos) , data) }) . collect () } ; let tokens = LazyAttrTokenStream :: new_pending (collect_pos . start_token , collect_pos . cursor_snapshot , num_calls , self . break_last_token , node_replacements ,) ; let mut tokens_used = false ; if definite_capture_mode { assert ! (self . break_last_token == 0 , "Should not have unglued last token with cfg attr") ; let start_pos = if has_outer_attrs { attrs . start_pos . unwrap () } else { collect_pos . start_pos } ; let target = AttrsTarget { attrs : ret_attrs . iter () . cloned () . collect () , tokens : tokens . clone () } ; tokens_used = true ; self . capture_state . parser_replacements . push ((ParserRange (start_pos .. end_pos) , Some (target))) ; } else if matches ! (self . capture_state . capturing , Capturing :: No) { self . capture_state . parser_replacements . clear () ; self . capture_state . inner_attr_parser_ranges . clear () ; self . capture_state . seen_attrs . clear () ; } if let Some (target_tokens @ None) = ret . tokens_mut () { tokens_used = true ; * target_tokens = Some (tokens) ; } assert ! (tokens_used) ; Ok (ret) } } #[doc = " Tokens are needed if:"] #[doc = " - any non-single-segment attributes (other than doc comments) are present,"] #[doc = "   e.g. `rustfmt::skip`; or"] #[doc = " - any `cfg_attr` attributes are present; or"] #[doc = " - any single-segment, non-builtin attributes are present, e.g. `derive`,"] #[doc = "   `test`, `global_allocator`."] fn needs_tokens (attrs : & [ast :: Attribute]) -> bool { attrs . iter () . any (| attr | match attr . ident () { None => ! attr . is_doc_comment () , Some (ident) => { ident . name == sym :: cfg_attr || ! rustc_feature :: is_builtin_attr_name (ident . name) } }) }